<script setup lang="ts">
import {computed, nextTick, onMounted, onUnmounted, ref, watch} from 'vue';
import {BookOpen, Plus, ArrowUpRight, ArrowLeft, ChevronDown, ChevronRight, X, Check, ImagePlus, Images, LineChart, Settings, LogOut, Download, Upload, Pencil, Trash2, LockKeyhole, Eye, EyeOff, CalendarDays, LoaderCircle, Heart, Search, FolderHeart, CheckCircle2, ShieldCheck, FileText} from 'lucide-vue-next';
import type {Data, Exam, Photo, Profile, Score} from './types';
import {EXAM_TYPES, getExamType} from '../shared/exam-types.js';
const dashboardUrl='/'+(new URLSearchParams(location.search).get('embed')==='ha'?'?embed=ha':'');
const ready=ref(false),configured=ref(true),signedIn=ref(false),password=ref(''),showPassword=ref(false),nickname=ref(''),authError=ref(''),busy=ref(false);
const data=ref<Data>({profile:{nickname:'孩子',subjects:['语文','数学','英语']},exams:[],photos:[]});
const demo=ref(false),tab=ref('records'),term=ref('全部学期'),typeFilter=ref('全部类型'),query=ref(''),notice=ref(''),noticeError=ref(false),detail=ref<Exam|null>(null),editor=ref<Exam|null>(null),lightbox=ref<Photo|null>(null);
const uploadKey=ref('');
const selectedFiles=ref<File[]>([]),fileUrls=ref<string[]>([]),formError=ref(''),savedId=ref(''),uploading=ref(false),savePending=ref(false),pendingPhotos=ref(false),subject=ref('语文'),point=ref('');
const profileDraft=ref<Profile>({nickname:'',subjects:[]}),subjectInput=ref(''),currentPassword=ref(''),newPassword=ref(''),passwordMessage=ref('');
const restore=ref<{token:string;nickname:string;exams:number;photos:number}|null>(null),restoreText=ref('');
const confirmDialog=ref<{title:string;body:string;action:()=>Promise<void>}|null>(null);
let noticeTimer:ReturnType<typeof setTimeout>;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function makeId(){if(typeof globalThis.crypto?.randomUUID==='function')return crypto.randomUUID();const a=new Uint8Array(16);globalThis.crypto.getRandomValues(a);a[6]=(a[6]!&15)|64;a[8]=(a[8]!&63)|128;const h=Array.from(a,b=>b.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
function toast(message:string,error=false){notice.value=message;noticeError.value=error;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',6000);}
async function api(url:string,options:RequestInit={}){const headers=new Headers(options.headers);headers.set('X-Requested-With','gradebook');if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');const res=await fetch('/api'+url,{...options,headers});if(!res.ok){const body=await res.json().catch(()=>({error:'连接失败，请稍后重试'}));if(res.status===401&&url!=='/login'){signedIn.value=false;}throw new Error(body.error||'操作失败');}return res.json();}
async function refresh(){data.value=await api('/data');if(detail.value)detail.value=data.value.exams.find(e=>e.id===detail.value?.id)||null;profileDraft.value=JSON.parse(JSON.stringify(data.value.profile));if(!data.value.profile.subjects.includes(subject.value))subject.value=data.value.profile.subjects[0]||'语文';}
async function authenticate(){authError.value='';busy.value=true;try{await api(configured.value?'/login':'/setup',{method:'POST',body:JSON.stringify({password:password.value,profile:{nickname:nickname.value||'孩子',subjects:['语文','数学','英语','物理','化学','生物','道德与法治','历史','地理']}})});signedIn.value=true;configured.value=true;password.value='';await refresh();}catch(e){authError.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{try{const a=await api('/auth');configured.value=a.configured;signedIn.value=a.authenticated;if(a.authenticated)await refresh();}catch(e){authError.value=(e as Error).message;}finally{ready.value=true;}});
onUnmounted(()=>{clearTimeout(noticeTimer);fileUrls.value.forEach(URL.revokeObjectURL);});
const terms=computed(()=>['全部学期',...Array.from(new Set(data.value.exams.map(e=>e.term))).sort().reverse()]);
const filtered=computed(()=>data.value.exams.filter(e=>(term.value==='全部学期'||e.term===term.value)&&(typeFilter.value==='全部类型'||(typeFilter.value==='未分类'?!getExamType(e):getExamType(e)===typeFilter.value))&&(!query.value||[e.title,e.note,e.grade,...e.scores.map(s=>s.subject)].some(v=>v.includes(query.value)))));
const latest=computed(()=>filtered.value[0]);
const rest=computed(()=>filtered.value.slice(1));
const totalPhotos=computed(()=>data.value.photos.length);
const filteredPhotos=computed(()=>data.value.photos.filter(p=>filtered.value.some(e=>e.id===p.examId)).length);
const chartRows=computed(()=>filtered.value.filter(e=>e.scores.some(s=>s.subject===subject.value)).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).map(e=>({exam:e,score:e.scores.find(s=>s.subject===subject.value)!})));
const chartPoints=computed(()=>chartRows.value.map((r,i)=>({x:chartRows.value.length===1?300:52+i*(496/(chartRows.value.length-1)),y:208-(r.score.score/r.score.max)*160,...r})));
const line=computed(()=>chartPoints.value.map(p=>`${p.x},${p.y}`).join(' '));
const average=computed(()=>chartRows.value.length?(chartRows.value.reduce((a,r)=>a+r.score.score/r.score.max*100,0)/chartRows.value.length).toFixed(1):'—');
const highest=computed(()=>chartRows.value.length?Math.max(...chartRows.value.map(r=>r.score.score/r.score.max*100)).toFixed(1):'—');
const selectedPoint=computed(()=>chartRows.value.find(r=>r.exam.id===point.value)||chartRows.value.at(-1));
const allSubjects=computed(()=>Array.from(new Set([...data.value.profile.subjects,...data.value.exams.flatMap(e=>e.scores.map(s=>s.subject))])));
function photosFor(id:string){return data.value.photos.filter(p=>p.examId===id);}
function photoUrl(p:Photo){return demo.value?'/demo-paper.svg':'/api/photos/'+p.id;}
function displayDate(date:string){return new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(new Date(date+'T12:00:00'));}
function fullDate(date:string){return date.replaceAll('-','.');}
function defaultTerm(){const d=new Date(),y=d.getFullYear(),m=d.getMonth()+1;return m>=8?`${y}–${y+1}学年 上学期`:m<=1?`${y-1}–${y}学年 上学期`:`${y-1}–${y}学年 下学期`;}
function openEditor(exam?:Exam){formError.value='';savedId.value='';pendingPhotos.value=false;selectedFiles.value=[];fileUrls.value.forEach(URL.revokeObjectURL);fileUrls.value=[];editor.value=exam?{...JSON.parse(JSON.stringify(exam)),examType:getExamType(exam)}:{id:makeId(),title:'',examType:'月考',date:today(),grade:data.value.exams[0]?.grade||'初一',term:term.value!=='全部学期'?term.value:data.value.exams[0]?.term||defaultTerm(),scores:data.value.profile.subjects.slice(0,3).map(s=>({subject:s,score:NaN,max:100})),note:''};}
function closeEditor(){if(busy.value||uploading.value||savePending.value)return;if(pendingPhotos.value){confirmDialog.value={title:'稍后补充照片？',body:'成绩已经保存，所选照片尚未上传。关闭后可以在考试详情中重新添加。',action:async()=>{editor.value=null;}};}else editor.value=null;}
function filesChanged(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(files.length>8){formError.value='每批最多选择 8 张照片';input.value='';return;}if(files.some(f=>f.size>12*1024*1024)){formError.value='每张照片请小于 12 MB';input.value='';return;}if(files.some(f=>!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(f.type))){formError.value='请选择 JPG、PNG 或 WebP 图片';input.value='';return;}fileUrls.value.forEach(URL.revokeObjectURL);selectedFiles.value=files;uploadKey.value=makeId();fileUrls.value=files.map(f=>URL.createObjectURL(f));pendingPhotos.value=files.length>0;formError.value='';input.value='';}
function removeFile(index:number){URL.revokeObjectURL(fileUrls.value[index]!);fileUrls.value.splice(index,1);selectedFiles.value.splice(index,1);pendingPhotos.value=selectedFiles.value.length>0;}
function updateExamType(){if(editor.value&&(!editor.value.title||EXAM_TYPES.some(t=>editor.value!.title===t||editor.value!.title===t+'考试')))editor.value.title=editor.value.examType==='月考'?'月考':editor.value.examType+'考试';}
async function saveExam(){if(!editor.value||busy.value||savePending.value)return;const e=editor.value;formError.value='';const scores=e.scores.filter(s=>Number.isFinite(s.score));if(!scores.length){formError.value='请至少填写一个科目的成绩';return;}if(scores.some(s=>!Number.isFinite(s.max)||s.max<=0||s.score<0||s.score>s.max)){formError.value='得分应在 0 到满分之间，满分必须大于 0';return;}if(new Set(scores.map(s=>s.subject)).size!==scores.length){formError.value='同一次考试不能填写重复科目';return;}let committed=false;try{const payload={...e,scores};for(const key of ['classRank','gradeRank'] as const){const value=e[key] as number|string|undefined;if(value===undefined||value===''){delete payload[key];}else if(typeof value!=='number'||!Number.isSafeInteger(value)||value<1){formError.value=(key==='classRank'?'班级排名':'年级排名')+'请填写大于 0 的整数，未知时留空';return;}}savePending.value=true;if(demo.value){const index=data.value.exams.findIndex(x=>x.id===e.id);if(index>=0)data.value.exams[index]=JSON.parse(JSON.stringify(payload));else data.value.exams.unshift(JSON.parse(JSON.stringify(payload)));data.value.exams.sort((a,b)=>b.date.localeCompare(a.date));editor.value=null;toast('演示记录已保存，退出演示后不会保留');return;}
  const exists=!!savedId.value||data.value.exams.some(x=>x.id===e.id);await api('/exams'+(exists?'/'+e.id:''),{method:exists?'PUT':'POST',body:JSON.stringify(payload)});savedId.value=e.id;committed=true;
  if(selectedFiles.value.length){uploading.value=true;const form=new FormData();selectedFiles.value.forEach(f=>form.append('photos',f));await api('/exams/'+e.id+'/photos',{method:'POST',body:form,headers:{'X-Upload-Id':uploadKey.value}});selectedFiles.value=[];fileUrls.value.forEach(URL.revokeObjectURL);fileUrls.value=[];pendingPhotos.value=false;}
  await refresh();editor.value=null;toast('这一次成长，已好好收藏');
}catch(err){formError.value=(committed?'成绩已保存；照片或刷新未完成，可重试。':'')+(err as Error).message;}finally{uploading.value=false;savePending.value=false;}}
async function removeExam(e:Exam){confirmDialog.value={title:'删除这次考试？',body:'成绩、小记和关联照片将一并删除。建议先导出备份。',action:async()=>{if(demo.value){data.value.exams=data.value.exams.filter(x=>x.id!==e.id);data.value.photos=data.value.photos.filter(p=>p.examId!==e.id);}else{await api('/exams/'+e.id,{method:'DELETE'});await refresh();}detail.value=null;toast('考试记录已删除');}};}
async function removePhoto(p:Photo){confirmDialog.value={title:'删除这张照片？',body:'删除后可重新上传原照片。',action:async()=>{if(demo.value)data.value.photos=data.value.photos.filter(x=>x.id!==p.id);else{await api('/photos/'+p.id,{method:'DELETE'});await refresh();}lightbox.value=null;toast('照片已删除');}};}
async function doConfirm(){if(!confirmDialog.value||busy.value)return;busy.value=true;try{await confirmDialog.value.action();confirmDialog.value=null;}catch(e){toast((e as Error).message,true);}finally{busy.value=false;}}
async function saveProfile(){busy.value=true;try{if(demo.value){data.value.profile=JSON.parse(JSON.stringify(profileDraft.value));toast('演示资料已更新');return;}await api('/profile',{method:'PUT',body:JSON.stringify(profileDraft.value)});await refresh();toast('资料已保存');}catch(e){toast((e as Error).message,true);}finally{busy.value=false;}}
function addSubject(){const s=subjectInput.value.trim();if(!s)return;if(profileDraft.value.subjects.includes(s)){toast('这个科目已经存在',true);return;}if(profileDraft.value.subjects.length>=30){toast('最多添加 30 个科目',true);return;}profileDraft.value.subjects.push(s);subjectInput.value='';}
async function changePassword(){busy.value=true;passwordMessage.value='';try{await api('/password',{method:'POST',body:JSON.stringify({current:currentPassword.value,password:newPassword.value})});currentPassword.value='';newPassword.value='';passwordMessage.value='密码已更新，其他登录已退出';}catch(e){passwordMessage.value=(e as Error).message;}finally{busy.value=false;}}
async function logout(){if(demo.value){demo.value=false;data.value={profile:{nickname:'孩子',subjects:['语文','数学','英语']},exams:[],photos:[]};detail.value=null;editor.value=null;term.value='全部学期';typeFilter.value='全部类型';tab.value='records';return;}try{await api('/logout',{method:'POST'});signedIn.value=false;data.value={profile:{nickname:'孩子',subjects:[]},exams:[],photos:[]};}catch(e){toast((e as Error).message,true);}}
async function previewBackup(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>200*1024*1024){toast('备份包不能超过 200 MB',true);return;}busy.value=true;try{const form=new FormData();form.append('backup',file);restore.value=await api('/restore/preview',{method:'POST',body:form});restoreText.value='';}catch(e){toast((e as Error).message,true);}finally{busy.value=false;}}
async function confirmRestore(){if(!restore.value||restoreText.value!=='替换现有记录')return;busy.value=true;try{await api('/restore/confirm',{method:'POST',body:JSON.stringify({token:restore.value.token,confirm:restoreText.value})});restore.value=null;term.value='全部学期';typeFilter.value='全部类型';await refresh();toast('备份已恢复，原数据已留存为恢复前备份');}catch(e){toast((e as Error).message,true);restore.value=null;}finally{busy.value=false;}}
function startDemo(){demo.value=true;tab.value='records';term.value='全部学期';typeFilter.value='全部类型';query.value='';data.value={profile:{nickname:'小禾',subjects:['语文','数学','英语','科学']},exams:[{id:'demo-1',title:'期中考试',date:'2026-11-06',grade:'五年级',term:'2026–2027学年 上学期',scores:[{subject:'语文',score:92,max:100},{subject:'数学',score:96,max:100},{subject:'英语',score:95,max:100}],note:'作文得到了老师的表扬。回家的路上，说自己终于敢举手读给大家听了。'},{id:'demo-2',title:'第三单元测试',date:'2026-10-16',grade:'五年级',term:'2026–2027学年 上学期',scores:[{subject:'数学',score:94,max:100}],note:'这次记得检查计算过程了。'},{id:'demo-3',title:'第一次月考',date:'2026-09-28',grade:'五年级',term:'2026–2027学年 上学期',scores:[{subject:'语文',score:88,max:100},{subject:'数学',score:90,max:100},{subject:'英语',score:93,max:100}],note:'新学期，慢慢找到自己的节奏。'}],photos:[{id:'demo-photo',examId:'demo-1',label:'示例试卷（非真实成绩）'}]};profileDraft.value=JSON.parse(JSON.stringify(data.value.profile));}
watch(tab,()=>{point.value='';query.value='';});
const overlay=computed(()=>!!editor.value||!!detail.value||!!lightbox.value||!!restore.value||!!confirmDialog.value);
const activeLayer=computed(()=>confirmDialog.value?'confirm':lightbox.value?'lightbox':restore.value?'restore':editor.value?'editor':detail.value?'detail':'');
let previousFocus:HTMLElement|null=null;
watch(activeLayer,async value=>{document.body.style.overflow=value?'hidden':'';if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();const nodes=document.querySelectorAll<HTMLElement>('[role="dialog"]');const dialog=nodes[nodes.length-1];(dialog?.querySelector<HTMLElement>('[autofocus]')||dialog?.querySelector<HTMLElement>('button, input, select, textarea')||dialog)?.focus();}else previousFocus?.focus();});
function keyboard(event:KeyboardEvent){if(!overlay.value)return;const dialogs=document.querySelectorAll<HTMLElement>('[role="dialog"]'),dialog=dialogs[dialogs.length-1];if(event.key==='Escape'&&!busy.value&&!savePending.value){if(confirmDialog.value)confirmDialog.value=null;else if(lightbox.value)lightbox.value=null;else if(restore.value)restore.value=null;else if(editor.value)closeEditor();else detail.value=null;}
if(event.key==='Tab'&&dialog){const nodes=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(!first)return;if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus();}}}
onMounted(()=>document.addEventListener('keydown',keyboard));onUnmounted(()=>{document.removeEventListener('keydown',keyboard);document.body.style.overflow='';});
</script>

<template>
  <div v-if="!ready" class="loading-screen"><LoaderCircle class="spin"/><p>正在打开学迹…</p></div>
  <main v-else-if="!signedIn && !demo" class="auth-layout">
    <div class="auth-story"><a class="brand"><span class="brand-icon"><BookOpen :size="24"/></span>学迹</a><div class="auth-copy"><span class="small-label">给成长，留一页记忆</span><h1>每一次认真，<br>都值得被珍藏。</h1><p>记下分数，也记下分数之外的故事。<br>多年以后，再一起翻开这些小小的成长。</p><div class="book-art" aria-hidden="true"><div class="book-spine"></div><div class="book-page"><span>成长手记</span><i></i><i></i><i></i><BookOpen :size="36"/><small>慢慢来，每一步都算数</small></div></div></div><span class="story-footer"><Heart :size="14"/> 一本只属于你们的成长记录</span></div>
    <div class="auth-form-wrap"><form class="auth-form" @submit.prevent="authenticate"><span class="brand-icon auth-icon"><BookOpen :size="26"/></span><span class="small-label">{{configured?'欢迎回来':'开始收藏成长'}}</span><h2>{{configured?'打开我们的成绩册':'创建私人​成绩册'}}</h2><p>{{configured?'输入密码，继续记录孩子的成长。':'首次使用，给成绩册设置一个私人密码。'}}</p><label v-if="!configured">孩子的昵称<input v-model="nickname" maxlength="24" placeholder="例如：小禾" autocomplete="nickname" required></label><label>私人密码<span class="password-input"><input v-model="password" :type="showPassword?'text':'password'" :autocomplete="configured?'current-password':'new-password'" :minlength="configured?1:10" maxlength="128" :placeholder="configured?'请输入密码':'至少 10 个字符'" required><button type="button" class="icon-button" :aria-label="showPassword?'隐藏密码':'显示密码'" @click="showPassword=!showPassword"><EyeOff v-if="showPassword" :size="18"/><Eye v-else :size="18"/></button></span></label><p v-if="authError" class="error" role="alert">{{authError}}</p><button class="primary full" :disabled="busy"><LoaderCircle v-if="busy" :size="18" class="spin"/><span>{{configured?'打开成绩册':'创建成绩册'}}</span><ArrowUpRight :size="18"/></button><div class="auth-separator"><span>先感受一下</span></div><button type="button" class="secondary full" @click="startDemo">查看示例成绩册 <ArrowUpRight :size="16"/></button><p class="privacy-note"><LockKeyhole :size="14"/> 数据保存在你的服务器，照片需要登录查看</p></form></div>
  </main>
  <div v-else class="app-shell" :inert="overlay || undefined">
    <aside class="sidebar"><a class="brand" href="#" @click.prevent="tab='records';detail=null"><span class="brand-icon"><BookOpen :size="23"/></span>学迹</a><div class="child-profile"><div class="avatar">{{data.profile.nickname.slice(0,1)}}</div><div><strong>{{data.profile.nickname}}的成长记录</strong><span>{{data.exams[0]?.grade||'从第一次记录开始'}}</span></div><Heart :size="16"/></div><nav aria-label="主要导航"><button :class="{active:tab==='records'}" @click="tab='records'"><BookOpen :size="19"/>考试记录<ChevronRight :size="15"/></button><button :class="{active:tab==='trends'}" @click="tab='trends'"><LineChart :size="19"/>成绩趋势<ChevronRight :size="15"/></button><button :class="{active:tab==='settings'}" @click="tab='settings'"><Settings :size="19"/>成绩册设置<ChevronRight :size="15"/></button></nav><div class="sidebar-bottom"><div class="sidebar-quote"><span class="quote-mark">“</span><p>成长有自己的节奏，<br>每一步都值得记录。</p><span>写给未来的你</span></div><button class="text-button" @click="logout"><LogOut :size="17"/>{{demo?'退出演示':'退出登录'}}</button></div></aside>
    <div class="main-wrap"><header class="topbar"><a class="mobile-brand" href="#" @click.prevent="tab='records'"><BookOpen :size="21"/>学迹</a><span class="desktop-breadcrumb">{{data.profile.nickname}}的成绩册 <ChevronRight :size="13"/> {{tab==='records'?'考试记录':tab==='trends'?'成绩趋势':'设置'}}</span><div class="topbar-right"><span class="private-badge"><LockKeyhole :size="12"/>私人收藏</span><span class="mini-avatar">{{data.profile.nickname.slice(0,1)}}</span></div></header>
    <div v-if="demo" class="demo-banner"><span>正在查看示例 · 所有记录均为演示数据，不会保存到服务器</span><button @click="logout">退出演示 <X :size="14"/></button></div>
    <main class="content"><a class="manage-back" :href="dashboardUrl"><ArrowLeft :size="16"/>返回成绩看板</a>
      <template v-if="tab==='records'">
        <section class="page-heading"><div><span class="small-label">把努力和故事，一起留下</span><h1>成长，一页一页收藏<span class="title-dot">。</span></h1><p>这里有每一次考试，也有每一个值得记住的瞬间。</p></div><button class="primary desktop-add" @click="openEditor()"><Plus :size="18"/>记录一次考试</button></section>
        <section class="summary-strip" aria-label="成绩册概览"><div><span class="summary-icon"><BookOpen :size="21"/></span><p><strong>{{data.exams.length}}<small>次</small></strong><span>认真走过的考试</span></p></div><div><span class="summary-icon"><Images :size="21"/></span><p><strong>{{totalPhotos}}<small>张</small></strong><span>好好收藏的照片</span></p></div><div><span class="summary-icon"><Heart :size="21"/></span><p><strong>{{data.exams.filter(e=>e.note).length}}<small>篇</small></strong><span>写给成长的小记</span></p></div></section>
        <div class="section-toolbar"><h2>考试记录 <span>{{filtered.length}}</span></h2><div class="filter-controls"><label class="select-wrap type-select"><select v-model="typeFilter" aria-label="筛选考试类型"><option>全部类型</option><option v-for="t in EXAM_TYPES" :key="t">{{t}}</option><option v-if="data.exams.some(e=>!getExamType(e))">未分类</option></select><ChevronDown :size="15"/></label><label class="search-box"><Search :size="16"/><input v-model="query" aria-label="搜索考试或小记" placeholder="搜索记录"></label><label class="select-wrap"><select v-model="term" aria-label="筛选学期"><option v-for="t in terms" :key="t">{{t}}</option></select><ChevronDown :size="15"/></label></div></div>
        <div v-if="!latest" class="empty-state"><FolderHeart :size="46" :stroke-width="1.2"/><h3>{{query||term!=='全部学期'||typeFilter!=='全部类型'?'还没有符合条件的记录':'成长的第一页，从这里开始'}}</h3><p>{{query||term!=='全部学期'||typeFilter!=='全部类型'?'试试其他关键词或学期。':'记下一次考试、留一张试卷，再写一句想记住的话。'}}</p><button v-if="!data.exams.length" class="primary" @click="openEditor()"><Plus :size="17"/>记录第一次考试</button><button v-else class="secondary" @click="query='';term='全部学期';typeFilter='全部类型'">查看全部记录</button></div>
        <template v-else><article class="featured-exam"><div class="featured-main"><div class="exam-meta"><span class="tag">最近一次</span><span><CalendarDays :size="14"/>{{fullDate(latest.date)}}</span></div><button class="exam-title-button" @click="detail=latest"><h3>{{latest.title}}</h3><ArrowUpRight :size="22"/></button><p class="exam-subtitle"><span class="exam-type-label">{{getExamType(latest)||'未分类'}}</span>{{latest.grade}} · {{latest.term}}</p><div v-if="latest.classRank || latest.gradeRank" class="exam-ranks"><span v-if="latest.classRank">班级第 <strong>{{latest.classRank}}</strong> 名</span><span v-if="latest.gradeRank">年级第 <strong>{{latest.gradeRank}}</strong> 名</span></div><div class="score-grid"><div v-for="s in latest.scores" :key="s.subject" class="score"><span>{{s.subject}}</span><p><strong>{{s.score}}</strong><small>/ {{s.max}}</small></p></div></div><div v-if="latest.note" class="exam-note"><span>“</span><p>{{latest.note}}</p></div><div class="featured-footer"><span><Images :size="15"/>{{photosFor(latest.id).length?photosFor(latest.id).length+' 张照片':'还未添加照片'}}</span><button class="text-button accent" @click="detail=latest">翻开这次记录<ArrowUpRight :size="16"/></button></div></div><div class="featured-memory" :class="{'has-photo':photosFor(latest.id).length}"><button v-if="photosFor(latest.id).length" class="photo-cover" @click="detail=latest"><img :src="photoUrl(photosFor(latest.id)[0]!)" alt="最近考试的试卷照片"><span><Images :size="16"/>查看照片</span></button><template v-else><div class="memory-lines" aria-hidden="true"><BookOpen :size="42" :stroke-width="1"/><i></i><i></i><i></i></div><p>把这一次努力<br>也留在相册里</p><button class="text-button" @click="openEditor(latest)">添加试卷照片 <Plus :size="15"/></button></template></div></article>
        <div v-if="rest.length" class="history-layout"><section class="timeline" aria-label="以往考试"><article v-for="e in rest" :key="e.id" class="timeline-row"><div class="timeline-date"><strong>{{displayDate(e.date)}}</strong><span>{{e.date.slice(0,4)}}</span></div><div class="timeline-marker"></div><button class="timeline-card" @click="detail=e"><div class="timeline-card-top"><h3><span>{{e.title}}</span> <span class="exam-type-small">{{getExamType(e)||'未分类'}}</span></h3><ChevronRight :size="18"/></div><div class="inline-scores"><span v-for="s in e.scores" :key="s.subject">{{s.subject}} <strong>{{s.score}}</strong><small>/{{s.max}}</small></span></div><div v-if="e.classRank || e.gradeRank" class="exam-ranks compact"><span v-if="e.classRank">班级第 <strong>{{e.classRank}}</strong> 名</span><span v-if="e.gradeRank">年级第 <strong>{{e.gradeRank}}</strong> 名</span></div><p v-if="e.note" class="timeline-note">{{e.note}}</p><span class="timeline-card-foot">{{e.grade}}<span v-if="photosFor(e.id).length"><Images :size="13"/>{{photosFor(e.id).length}} 张照片</span></span></button></article></section><aside class="memory-aside"><span class="small-label">不止是分数</span><h3>也记下<br>那些闪光的小事。</h3><p>一道终于弄懂的题，<br>一次主动举起的手，<br>一份比昨天多一点的勇气。</p><Heart :size="25" :stroke-width="1.3"/></aside></div><footer class="records-end"><span></span>每一次记录，都是成长的回响<span></span></footer></template>
        <button class="mobile-add primary" aria-label="记录一次考试" @click="openEditor()"><Plus :size="22"/>记一笔</button>
      </template>
      <template v-else-if="tab==='trends'"><section class="page-heading"><div><span class="small-label">看见每一步的变化</span><h1>努力，自有轨迹<span class="title-dot">。</span></h1><p>用得分率比较不同满分的考试，也记得每次试卷的难度不同。</p></div><div class="trend-filters"><label class="select-wrap"><select v-model="typeFilter" aria-label="趋势考试类型"><option>全部类型</option><option v-for="t in EXAM_TYPES" :key="t">{{t}}</option><option v-if="data.exams.some(e=>!getExamType(e))">未分类</option></select><ChevronDown :size="15"/></label><label class="select-wrap"><select v-model="term" aria-label="趋势学期"><option v-for="t in terms" :key="t">{{t}}</option></select><ChevronDown :size="15"/></label></div></section><div class="subject-tabs" aria-label="选择科目"><button v-for="s in allSubjects" :key="s" :class="{active:subject===s}" :aria-pressed="subject===s" @click="subject=s;point=''">{{s}}</button></div><div v-if="!chartRows.length" class="empty-state"><LineChart :size="44"/><h3>这门课的故事，还等你记录</h3><p>保存成绩后，就能在这里查看变化。</p><button class="primary" @click="openEditor()"><Plus :size="17"/>记录一次考试</button></div><template v-else><div class="trend-summary"><div><span>记录次数</span><strong>{{chartRows.length}}<small>次</small></strong></div><div><span>平均得分率</span><strong>{{average}}<small>%</small></strong></div><div><span>最高得分率</span><strong>{{highest}}<small>%</small></strong></div></div><section class="chart-card"><div class="section-toolbar"><h2>{{subject}}的成长曲线</h2><span class="muted">得分率 %</span></div><svg class="trend-chart" viewBox="0 0 600 250" role="group" :aria-label="subject+'成绩得分率趋势，下面有完整考试列表'"><g v-for="n in [0,25,50,75,100]" :key="n"><line x1="52" x2="548" :y1="208-n*1.6" :y2="208-n*1.6" stroke="#e3e8f1" stroke-dasharray="3 6"/><text x="35" :y="213-n*1.6" text-anchor="end" fill="#607088" font-size="12">{{n}}</text></g><polygon v-if="chartPoints.length>1" :points="`52,208 ${line} 548,208`" fill="#496bed" opacity=".07"/><polyline :points="line" fill="none" stroke="#385cf6" stroke-width="2.5" stroke-linejoin="round"/><g v-for="(p,i) in chartPoints" :key="p.exam.id"><circle :cx="p.x" :cy="p.y" r="18" fill="transparent" tabindex="0" role="button" :aria-label="p.exam.title+'，得分率 '+(p.score.score/p.score.max*100).toFixed(1)+'%'" @click="point=p.exam.id" @keydown.enter.prevent="point=p.exam.id" @keydown.space.prevent="point=p.exam.id"/><circle :cx="p.x" :cy="p.y" :r="selectedPoint?.exam.id===p.exam.id?6:4" fill="#385cf6" stroke="#ffffff" stroke-width="3"/><text v-if="i===0||i===chartPoints.length-1" :x="p.x" y="235" text-anchor="middle" fill="#607088" font-size="12">{{p.exam.date.slice(5).replace('-','/')}}</text></g></svg><div v-if="selectedPoint" class="chart-caption"><span>{{fullDate(selectedPoint.exam.date)}} · {{selectedPoint.exam.title}}</span><strong>{{selectedPoint.score.score}} / {{selectedPoint.score.max}} <small>（{{(selectedPoint.score.score/selectedPoint.score.max*100).toFixed(1)}}%）</small></strong></div><p v-if="chartRows.length===1" class="hint">已有第一份记录，下一次考试后就能连成曲线。</p></section><section class="trend-list"><h2>每一次的成绩</h2><button v-for="r in chartRows.slice().reverse()" :key="r.exam.id" @click="point=r.exam.id;detail=r.exam"><span><strong>{{r.exam.title}}</strong><small>{{fullDate(r.exam.date)}}</small></span><span class="trend-value">{{r.score.score}}<small>/ {{r.score.max}}</small><ChevronRight :size="16"/></span></button></section></template></template>
      <template v-else><section class="page-heading"><div><span class="small-label">让回忆，安心留存</span><h1>打理我们的成绩册<span class="title-dot">。</span></h1><p>设置孩子的资料，也为珍贵的记录留一份备份。</p></div></section><div class="settings-grid"><form class="settings-card" @submit.prevent="saveProfile"><div class="card-heading"><BookOpen :size="20"/><h2>孩子与科目</h2></div><label>孩子的昵称<input v-model="profileDraft.nickname" required maxlength="24"></label><label>常用科目<span class="hint">调整科目不会改变以往考试记录</span></label><div class="subject-chips"><span v-for="(s,i) in profileDraft.subjects" :key="s">{{s}}<button type="button" :aria-label="'移除'+s" :disabled="profileDraft.subjects.length===1" @click="profileDraft.subjects.splice(i,1)"><X :size="13"/></button></span></div><div class="input-action"><input v-model="subjectInput" maxlength="24" placeholder="添加其他科目" aria-label="新科目名称" @keydown.enter.prevent="addSubject"><button type="button" class="secondary" @click="addSubject"><Plus :size="17"/>添加</button></div><button class="primary" :disabled="busy">保存资料 <Check :size="16"/></button></form><section class="settings-card"><div class="card-heading"><ShieldCheck :size="20"/><h2>备份与恢复</h2></div><p class="settings-description">完整备份包含成绩、照片和小记。建议每学期保存一份到其他设备。</p><template v-if="!demo"><a href="/api/backup" class="backup-action"><span class="backup-icon"><Download :size="21"/></span><span><strong>导出完整备份</strong><small>ZIP · 成绩、照片和小记</small></span><ArrowUpRight :size="17"/></a><a href="/api/csv" class="backup-action"><span class="backup-icon"><FileText :size="21"/></span><span><strong>导出成绩表</strong><small>CSV · 可用 Excel 打开</small></span><ArrowUpRight :size="17"/></a><label class="backup-action upload-backup" :class="{disabled:busy}"><span class="backup-icon"><Upload :size="21"/></span><span><strong>{{busy?'正在读取…':'从备份恢复'}}</strong><small>先预览，再确认替换现有记录</small></span><ChevronRight :size="17"/><input type="file" accept=".zip" :disabled="busy" @change="previewBackup"></label><a v-if="data.recoveryAvailable" class="text-button recovery-link" href="/api/recovery-backup">下载上次恢复前的备份</a><p class="hint">备份包超过 200 MB 时，可在 NAS 上备份完整数据目录。</p></template><p v-else class="hint">备份、恢复和密码功能在正式成绩册中可用。</p></section><form v-if="!demo" class="settings-card" @submit.prevent="changePassword"><div class="card-heading"><LockKeyhole :size="20"/><h2>私人密码</h2></div><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" maxlength="128" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" placeholder="至少 10 个字符" required></label><p v-if="passwordMessage" role="status" class="hint">{{passwordMessage}}</p><button class="secondary" :disabled="busy">更新密码</button></form><section class="settings-card about-card"><div class="card-heading"><Heart :size="20"/><h2>关于这本成绩册</h2></div><p>分数是成长的一部分，<br>认真、勇气和快乐也是。</p><div class="storage-note"><LockKeyhole :size="16"/><span>记录保存在自己的服务器<br>照片仅登录后可见</span></div><button class="text-button" @click="logout"><LogOut :size="16"/>{{demo?'退出演示':'退出登录'}}</button></section></div></template>
    </main><nav class="mobile-nav" aria-label="手机导航"><button :class="{active:tab==='records'}" @click="tab='records'"><BookOpen :size="21"/><span>记录</span></button><button :class="{active:tab==='trends'}" @click="tab='trends'"><LineChart :size="21"/><span>趋势</span></button><button :class="{active:tab==='settings'}" @click="tab='settings'"><Settings :size="21"/><span>设置</span></button></nav></div>
  </div>
  <div v-if="detail" :inert="!!editor || !!lightbox || !!confirmDialog || undefined" class="modal-backdrop" @click.self="detail=null"><section class="modal detail-modal" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="modal-head"><span class="small-label">成长档案</span><button class="icon-button" aria-label="关闭详情" @click="detail=null"><X :size="21"/></button></div><div class="detail-heading"><span class="muted">{{fullDate(detail.date)}} · {{detail.grade}}</span><h2 id="detail-title">{{detail.title}}</h2><p><span class="exam-type-label">{{getExamType(detail)||'未分类'}}</span>{{detail.term}}</p><div v-if="detail.classRank || detail.gradeRank" class="exam-ranks"><span v-if="detail.classRank">班级第 <strong>{{detail.classRank}}</strong> 名</span><span v-if="detail.gradeRank">年级第 <strong>{{detail.gradeRank}}</strong> 名</span></div></div><div class="score-grid"><div v-for="s in detail.scores" :key="s.subject" class="score"><span>{{s.subject}}</span><p><strong>{{s.score}}</strong><small>/ {{s.max}}</small></p></div></div><div class="detail-note"><span class="small-label">这一次的小记</span><p>{{detail.note||'还没有写下小记，可以补上一句当时的心情。'}}</p></div><div class="section-toolbar"><h3>收藏的照片 <span class="muted">{{photosFor(detail.id).length}}</span></h3><button class="text-button accent" @click="openEditor(detail)"><ImagePlus :size="17"/>添加照片</button></div><div v-if="photosFor(detail.id).length" class="photo-grid"><button v-for="p in photosFor(detail.id)" :key="p.id" @click="lightbox=p"><img :src="photoUrl(p)" :alt="p.label" loading="lazy"></button></div><div v-else class="photo-empty"><Images :size="28"/><p>拍下试卷，把这份努力留下。</p></div><div class="modal-actions"><button class="text-button danger" @click="removeExam(detail)"><Trash2 :size="16"/>删除记录</button><button class="primary" @click="openEditor(detail)"><Pencil :size="16"/>编辑记录</button></div></section></div>
  <div v-if="editor" :inert="!!confirmDialog || undefined" class="modal-backdrop editor-backdrop" @click.self="closeEditor"><form class="modal editor-modal" role="dialog" aria-modal="true" aria-labelledby="editor-title" tabindex="-1" @submit.prevent="saveExam"><div class="modal-head sticky-head"><div><span class="small-label">收藏一次成长</span><h2 id="editor-title">{{data.exams.some(e=>e.id===editor?.id)||savedId?'编辑考试记录':'记录一次考试'}}</h2></div><button class="icon-button" type="button" aria-label="关闭录入" :disabled="savePending" @click="closeEditor"><X :size="21"/></button></div><div class="editor-body"><label>考试类型<select v-model="editor.examType" aria-label="考试类型" required @change="updateExamType"><option :value="undefined" disabled>请选择考试类型</option><option v-for="t in EXAM_TYPES" :key="t" :value="t">{{t}}</option></select></label><label>考试名称<input v-model="editor.title" autofocus required maxlength="80" placeholder="例如：10 月月考、期中考试"></label><div class="form-row"><label>考试日期<input v-model="editor.date" type="date" required></label><label>年级<select v-model="editor.grade"><option v-for="g in ['一年级','二年级','三年级','四年级','五年级','六年级','初一','初二','初三','高一','高二','高三']" :key="g">{{g}}</option><option v-if="!['一年级','二年级','三年级','四年级','五年级','六年级','初一','初二','初三','高一','高二','高三'].includes(editor.grade)">{{editor.grade}}</option></select></label></div><label>所属学期<input v-model="editor.term" list="term-options" maxlength="40" required placeholder="例如：2026–2027学年 上学期"><datalist id="term-options"><option v-for="t in terms.filter(t=>t!=='全部学期')" :key="t" :value="t"/></datalist></label><div class="editor-section-title"><h3>本次考试总排名</h3><span class="hint">选填 · 没公布可留空</span></div><div class="form-row rank-inputs"><label>班级排名<input v-model.number="editor.classRank" type="number" min="1" step="1" inputmode="numeric" placeholder="例如：5"></label><label>年级排名<input v-model.number="editor.gradeRank" type="number" min="1" step="1" inputmode="numeric" placeholder="例如：28"></label></div><div class="editor-section-title"><h3>各科成绩</h3><span class="hint">只填已出分的科目</span></div><div class="score-input-labels"><span>科目</span><span>得分</span><span>满分</span><span></span></div><div v-for="(s,i) in editor.scores" :key="i" class="score-input-row"><select v-model="s.subject" :aria-label="`第 ${i+1} 项科目`"><option v-for="sub in Array.from(new Set([...allSubjects,s.subject]))" :key="sub">{{sub}}</option></select><input v-model.number="s.score" type="number" min="0" :max="s.max" step="0.01" inputmode="decimal" placeholder="未出分" :aria-label="s.subject+'得分'"><input v-model.number="s.max" type="number" min="0.01" max="10000" step="0.01" inputmode="decimal" :aria-label="s.subject+'满分'" required><button class="icon-button" type="button" :aria-label="'移除'+s.subject" :disabled="editor.scores.length===1" @click="editor.scores.splice(i,1)"><X :size="17"/></button></div><button v-if="editor.scores.length<30" class="text-button accent add-subject" type="button" @click="editor.scores.push({subject:allSubjects.find(s=>!editor?.scores.some(x=>x.subject===s))||allSubjects[0]||'语文',score:NaN,max:100})"><Plus :size="16"/>添加科目</button><div class="editor-section-title"><h3>试卷与照片</h3><span class="hint">选填 · 每批最多 8 张</span></div><label class="photo-upload"><ImagePlus :size="25"/><strong>选择照片或拍照</strong><span>JPG / PNG / WebP，每张不超过 12 MB</span><input type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple @change="filesChanged"></label><div v-if="selectedFiles.length" class="selected-photos"><div v-for="(f,i) in selectedFiles" :key="f.name+i"><img :src="fileUrls[i]" :alt="f.name"><button type="button" :aria-label="'取消上传'+f.name" @click="removeFile(i)"><X :size="14"/></button></div></div><p v-if="photosFor(editor.id).length" class="hint">已保存 {{photosFor(editor.id).length}} 张照片，可在详情中查看和删除。</p><label class="note-label">这一次的小记 <span class="optional">选填</span><textarea v-model="editor.note" rows="4" maxlength="3000" placeholder="孩子说了什么？有什么小进步？写下一句想记住的话。"></textarea><span class="character-count">{{editor.note.length}} / 3000</span></label><p v-if="formError" class="error" role="alert">{{formError}}</p></div><div class="modal-actions sticky-actions"><button type="button" class="secondary" :disabled="savePending" @click="closeEditor">稍后再记</button><button class="primary" :disabled="savePending"><LoaderCircle v-if="savePending" :size="17" class="spin"/><Check v-else :size="17"/>{{uploading?'正在上传照片…':savePending?'正在保存…':'保存这次成长'}}</button></div></form></div>
  <div v-if="lightbox" :inert="!!confirmDialog || undefined" class="lightbox" role="dialog" aria-modal="true" aria-label="照片查看" tabindex="-1"><div class="lightbox-toolbar"><span>{{lightbox.label}}</span><div><button class="icon-button" aria-label="删除照片" @click="removePhoto(lightbox!)"><Trash2 :size="21"/></button><a v-if="!demo" class="icon-button" :href="photoUrl(lightbox)" download="试卷照片.webp" aria-label="下载照片"><Download :size="21"/></a><button class="icon-button" aria-label="关闭照片" @click="lightbox=null"><X :size="24"/></button></div></div><div class="lightbox-image"><img :src="photoUrl(lightbox)" :alt="lightbox.label"></div><p>可用双指放大查看照片细节</p></div>
  <div v-if="restore" class="modal-backdrop confirm-backdrop"><section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="restore-title" tabindex="-1"><div class="modal-head"><h2 id="restore-title">恢复这份成长记录？</h2><button class="icon-button" aria-label="取消恢复" :disabled="busy" @click="restore=null"><X :size="21"/></button></div><div class="restore-summary"><strong>{{restore.nickname}}的成绩册</strong><span>{{restore.exams}} 次考试 · {{restore.photos}} 张照片</span></div><p>恢复会替换当前成绩、照片和昵称，登录密码保持不变。系统会先保存一份恢复前备份。</p><label>输入「替换现有记录」以确认<input v-model="restoreText" autocomplete="off"></label><div class="modal-actions"><button class="secondary" :disabled="busy" @click="restore=null">取消</button><button class="primary" :disabled="busy||restoreText!=='替换现有记录'" @click="confirmRestore">{{busy?'正在恢复…':'确认恢复'}}</button></div></section></div>
  <div v-if="confirmDialog" class="modal-backdrop confirm-backdrop"><section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="confirm-title" tabindex="-1"><div class="modal-head"><h2 id="confirm-title">{{confirmDialog.title}}</h2><button class="icon-button" aria-label="取消" :disabled="busy" @click="confirmDialog=null"><X :size="21"/></button></div><p>{{confirmDialog.body}}</p><div class="modal-actions"><button class="secondary" :disabled="busy" @click="confirmDialog=null">取消</button><button class="primary" :disabled="busy" @click="doConfirm">{{busy?'正在处理…':'确认'}}</button></div></section></div>
  <div v-if="notice" class="toast" :class="{error:noticeError}" role="status"><CheckCircle2 v-if="!noticeError" :size="19"/><span>{{notice}}</span><button class="icon-button" aria-label="关闭提示" @click="notice=''"><X :size="16"/></button></div>
</template>
